import{d as c,C as t,o as u,c as p,j as a,a as o,E as r,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第四十三章","description":"从至柔通至坚、无有入无间，理解无为之益与不言之教。","frontmatter":{"title":"道德经第四十三章","description":"从至柔通至坚、无有入无间，理解无为之益与不言之教。","category":"guide","aliases":["道德经第四十三章","老子第四十三章","dao de jing chapter 43"],"source":["王弼《道德真经注》卷三"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-43.md","filePath":"daoism/dao-de-jing/chapter-43.md","lastUpdated":1794189804000}'),b={name:"daoism/dao-de-jing/chapter-43.md"},P=c({...b,setup(g){const i=[{id:"softness-through-hardness",label:"天下之至柔",showLabel:!0,sentences:[["天下之至柔，",{text:"驰骋",glossary:"chicheng"},"天下之至坚。"]],note:["【白话】天下最柔弱的，可以通行于天下最坚硬的之中。这里用驰骋形容作用的通达，并不只比较表面上的力量强弱。","【王弼注择要】「气无所不入。」王弼以气的取象说明至柔的通达；所据后接水句有难明字样，本页不擅改为另一句后引用。","【读法】至柔取古代气、水之喻来理解，不是宣称任何柔软材料都能穿透一切坚硬物，也不以此要求人在强制面前一概退让。"]},{id:"formlessness-and-nonaction",label:"无有入无间",showLabel:!0,sentences:[[{text:"无有",glossary:"wuyou"},"入",{text:"无间",glossary:"wujian"},"。吾是以知",{text:"无为",glossary:"wuwei"},"之有益。"]],note:["【白话】不具固定形质的，能够进入没有间隙之处。我由此知道，不妄作、无所执限的作为，有其益处。","【王弼注择要】「虚无柔弱，无所不通。」又说「以此推之，故知无为之有益也」，把无有入无间与无为相联。","【读法】无有在这里取不具固定形质之义，不简单译成什么也没有；无间指没有空隙。此是推论性的取象，不能据此许诺遇到任何阻碍都可不行动而解决。"]},{id:"teaching-without-imposition",label:"不言之教",showLabel:!0,sentences:[["不言之教，",{text:"无为",glossary:"wuwei"},"之益，天下",{text:"希",glossary:"xi"},"及之。"]],note:["【白话】不靠言说强加于人的教导，以及无为所带来的益处，天下很少有人能够企及。","【读法】所据录文此句未另见独立王注，不补造引文。不言之教可连第二章读，重点在不以言说自居为主、以实际成物体现教导；不排斥必要的解释、沟通与教学。","【读法】希在此作少，及作达到。将不言实践为少一点空说，应同时检查行动是否确实有益，而非用沉默替代回应。"]}],n=[{id:"chicheng",term:"驰骋",sense:1},{id:"wuyou",term:"无有",sense:1},{id:"wujian",term:"无间",sense:1},{id:"wuwei",term:"无为",sense:1},{id:"xi",term:"希",sense:2}];return(x,e)=>{const s=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),p("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第四十三章",tabindex:"-1"},[o("道德经第四十三章 "),a("a",{class:"header-anchor",href:"#道德经第四十三章","aria-label":'Permalink to "道德经第四十三章"'},"​")],-1)),r(s,{title:"至柔怎样通行于至坚之间",summary:"本章以至柔与至坚、无有与无间两组对照，推到无为的益处，再落到不言之教。王弼从气、柔弱与虚无的通达来解释，关键在不被固定形质所限。",points:[{label:"先读",text:"驰骋在这里写通达、穿行，不按骑马奔跑逐字直译。"},{label:"再辨",text:"无有、无间是两组概念，间读 jiàn，指间隙。"},{label:"后看",text:"不言之教不等于停止沟通，无为之益也不等于省去一切行动。"}],hint:"驰骋读 chí chěng，无间的间读 jiàn；天下希及之的希取稀少义，与听之不闻的希分义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[o("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),r(l,{sections:i,glossary:n}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[o("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"天下之至柔，驰骋天下之至坚。",tone:"柔弱与通达",guide:"先看气的取象，再问哪些执限反而使行动受阻。"},{text:"无有入无间。吾是以知无为之有益。",tone:"由取象推知无为",guide:"无有取无固定形质，不直接等同什么都没有。"},{text:"不言之教，无为之益，天下希及之。",tone:"教导也看成用",guide:"以实际成全说明不言之教，同时保留必要沟通。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[o("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),r(h,{items:n}),e[4]||(e[4]=m('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-两组对照怎样走向结尾" tabindex="-1">象：两组对照怎样走向结尾？ <a class="header-anchor" href="#象-两组对照怎样走向结尾" aria-label="Permalink to &quot;象：两组对照怎样走向结尾？&quot;">​</a></h3><p>至柔通至坚，无有入无间，都在松动唯有强硬形质才能发挥作用的想法。文本再由此推知无为之益，最后以少有人能及提醒这是一种难以实践的教导方式。</p><h3 id="理-为何不把无有译成绝对的不存在" tabindex="-1">理：为何不把无有译成绝对的不存在？ <a class="header-anchor" href="#理-为何不把无有译成绝对的不存在" aria-label="Permalink to &quot;理：为何不把无有译成绝对的不存在？&quot;">​</a></h3><p>本章以入与通达描述作用。依王弼虚无柔弱的解释，无有侧重不受固定形质所限；若径译成彻底不存在，容易把它与后面的实际成用割断。</p><h3 id="用-怎样理解今天的不言之教" tabindex="-1">用：怎样理解今天的不言之教？ <a class="header-anchor" href="#用-怎样理解今天的不言之教" aria-label="Permalink to &quot;用：怎样理解今天的不言之教？&quot;">​</a></h3><p>可以少一些重复训示，多用行动、环境和一致的做法帮助理解。需要说清的责任、规则与反馈仍要说清，沉默本身并不保证有教益。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>让方法保留伸缩。</strong> 既定做法走不通时，观察阻碍来自实际条件还是自己执定的形式。调整表达、节奏和协作方式，可能比继续加压更能推进事情。</p><p><strong>用行为支持所说的话。</strong> 比起反复要求他人，稳定兑现自己的承诺往往更能形成信任。不言之教可借此理解，也仍需让对方有表达困惑的渠道。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我是否把强硬当作唯一有效的行动方式？哪些话需要说清，哪些反复的训示可以由一致的行动来承担？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文与标点沿本站保留，与卷三 008a 电子录文相核。</li><li>王注气句后接的水句录文难明，只节引气无所不入；末句未另见独立注，不补造原注。</li><li>无有、无间按本句组合释义；希新增稀少义，保留第十四章及第四十一章听而不闻的旧义。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_003.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷三 HFL 本电子录文，008a</a>。</p>',15))])}}});export{_ as __pageData,P as default};
